def read_file_content(path):
    if not isinstance(path, str):
        return "Error: 路径必须是字符串"
    try:
        with open(path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return "Error: 文件未找到"
    except IOError:
        return "Error: 读取文件时发生错误"
```

