def concatenate_strings(s1, s2):
    if not isinstance(s1, str) or not isinstance(s2, str):
        return "Error: 输入必须为字符串"
    try:
        return s1 + s2
    except Exception as e:
        return f"Error: 连接字符串时发生错误 - {str(e)}"

