def remove_element_by_index(lst, index):
    if index < 0 or index >= len(lst):
        return "Error: 索引超出范围"
    try:
        new_lst = lst[:index] + lst[index+1:]
        return new_lst
    except Exception as e:
        return f"Error: {str(e)}"
```

