def json_to_dict(json_str):
    if not isinstance(json_str, str):
        return "Error: 输入不是字符串"
    try:
        import json
        return json.loads(json_str)
    except json.JSONDecodeError:
        return "Error: 格式不正确，无法解析为字典"
